import { auth } from '@/lib/auth';
import { redirect, notFound } from 'next/navigation';
import { prisma } from '@/lib/prisma';
import Link from 'next/link';
import { AdminBillingUserClient } from '@/components/admin/billing-page-client';
import { formatMoney } from '@/lib/utils';

export default async function AdminBillingUserPage({
  params,
}: {
  params: Promise<{ userId: string }>;
}) {
  const session = await auth();
  if (!session || session.user.role !== 'ADMIN') redirect('/dashboard');

  const { userId } = await params;

  const user = await prisma.user.findUnique({
    where: { id: userId },
    include: {
      assignedAgents: {
        include: { agent: { select: { name: true, retellAgentId: true } } },
        orderBy: { assignedAt: 'desc' },
      },
    },
  });

  if (!user) notFound();

  const invoicesRaw = await prisma.invoice.findMany({
    where: { userId },
    orderBy: { createdAt: 'desc' },
    include: { _count: { select: { lineItems: true } } },
  });

  const invoices = invoicesRaw.map(inv => ({
    id: inv.id,
    invoiceNumber: inv.invoiceNumber,
    periodStart: inv.periodStart.toISOString(),
    periodEnd: inv.periodEnd.toISOString(),
    status: inv.status as 'DRAFT' | 'PENDING' | 'PAID' | 'OVERDUE' | 'CANCELLED',
    total: Number(inv.total),
    lineItemsCount: inv._count.lineItems,
    paidAt: inv.paidAt?.toISOString() ?? null,
    createdAt: inv.createdAt.toISOString(),
  }));

  return (
    <div className="space-y-8">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500">
        <Link href="/admin/billing" className="hover:text-gray-700">Billing</Link>
        <span>›</span>
        <span className="text-gray-900 font-medium">{user.name || user.email}</span>
      </div>

      {/* User Header */}
      <div>
        <h1 className="text-2xl font-bold text-gray-900">{user.name || '—'}</h1>
        <p className="text-gray-500 mt-0.5">{user.email}</p>
      </div>

      {/* Agent Pricing Summary */}
      {user.assignedAgents.length > 0 && (
        <section className="space-y-3">
          <h2 className="text-sm font-semibold text-gray-700 uppercase tracking-wide">Agent Pricing</h2>
          <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-100 bg-gray-50">
                  <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Agent</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Setup Fee</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Setup Paid</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Monthly Fee</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Per-Min Rate</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {user.assignedAgents.map(ua => (
                  <tr key={ua.id} className="hover:bg-gray-50">
                    <td className="px-4 py-3 font-medium text-gray-900">{ua.agent.name}</td>
                    <td className="px-4 py-3 text-right text-gray-600">{formatMoney(ua.setupFee ? Number(ua.setupFee) : null)}</td>
                    <td className="px-4 py-3 text-right">
                      <span className={`text-xs font-medium ${ua.setupFeePaid ? 'text-green-600' : 'text-gray-400'}`}>
                        {ua.setupFeePaid ? 'Yes' : 'No'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right text-gray-600">{formatMoney(ua.monthlyFee ? Number(ua.monthlyFee) : null)}</td>
                    <td className="px-4 py-3 text-right text-gray-600">
                      {ua.customPrice ? `$${Number(ua.customPrice).toFixed(4)}/min` : '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}

      {/* Invoices */}
      <section className="space-y-3">
        <h2 className="text-sm font-semibold text-gray-700 uppercase tracking-wide">Invoices</h2>
        <AdminBillingUserClient userId={userId} invoices={invoices} />
      </section>
    </div>
  );
}
